/**
 * Facts extracted from private gameplay captures (colosseum-sol-heredit-packet-data.txt, colosseum-sol-heredit-solar-flare-doom-volatility-packet-data.txt, colosseum-sol-heredit-packet-data-2.txt, colosseum-sol-heredit-long-fight-packet-data-3.txt, colosseum-waves-1-12-damage-trials-solarflare3-volatility3-bees1-totemic-doom1-death-packet-data.txt).
 * Sol Heredit's crystal beam rounds and molten sand pools, as capture ticks, with tiles relative to
 * the Colosseum arena origin (world 1792, 3072).
 *
 * `SOL_BEAM_TIMELINES`, from Sol's add onward: Sol's phase taunts (`[tick, say text]`, the lines matching
 * `SOL_PHASE_TRANSITIONS`), each beam crystal (its add tick and tile,
 * its walk/crawl destinations by tick, whether its NPC index is below Sol's, and its despawn sequence
 * 10800 and `del` ticks), the 8253 warning sound ticks, Sol's attack-sequence ticks (10883-10887), the
 * crystal charge (10801) and fire (10802) sequence ticks, the beam map_anims 2689-2697 per tick as
 * `[id, x, y, delay]`, and Sol's death: his death sequence 10888 (`killed`) or his removal.
 *
 * `SOL_POOL_DEATHS`: per tile, the tick its first holy-fire pool LOC (50746) was added; the sand
 * strike map_anims (2698) per tick; the pool despawn loc_anims (10814) per tick; the
 * `invisible_type8_nonblocking` (29733) replacements per tick; and the death-sequence tick. Tiles are
 * `"x,y"`.
 */
import type { Coordinate } from '../../../../types/simulation';

type TickTiles = readonly (readonly [tick: number, tiles: readonly string[]])[];

export interface CapturedBeamTimeline {
  readonly taunts: readonly (readonly [tick: number, text: string])[];
  readonly crystals: readonly {
    readonly added: number;
    readonly at: Coordinate;
    readonly moves: readonly (readonly [tick: number, to: Coordinate])[];
    readonly beforeSol: boolean;
    readonly despawned?: number;
    readonly removed?: number;
  }[];
  readonly warnings: readonly number[];
  readonly telegraphs: readonly number[];
  readonly charges: readonly number[];
  readonly fires: readonly number[];
  readonly beamGraphics: readonly (readonly [
    tick: number,
    graphics: readonly (readonly [spotAnimId: number, x: number, y: number, delayCycles: number])[],
  ])[];
  readonly death: number;
  readonly killed: boolean;
}

export interface CapturedPoolDeath {
  readonly formed: readonly (readonly [tile: string, tick: number])[];
  readonly strikes: TickTiles;
  readonly despawnAnims: TickTiles;
  readonly replaced: TickTiles;
  readonly death: number;
}

